import java.io.*;
import java.util.Scanner;
public class JWorkHours2 {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        System.out.println("Adkhil ism al-malaf:");
        String name = scan.next();
        JWorkHours2 jwh = new JWorkHours2();
        jwh.reportWorkHours(name);
    }
    //Khatwa 1: Ta'reef al-tareeqa allati tata'amal ma'a malaf al-muwazzafin
    public void reportWorkHours(String fileName) {
        //Khatwa 1.1: Ahtawa al-kod alladhi qad yurmee istithna'a dakhil qita' try
        try {
            //Khatwa 1.1.1: Istakhdim BufferedReader ma'a FileReader
            FileReader fr = new FileReader(fileName); 
            BufferedReader br = new BufferedReader(fr); 
            //Khatwa 1.1.2: Istakhdim object BufferedReader li qira'at satar wahid fi al-waqt
            String line = null;
            while ( ( line = br.readLine() ) != null) {
                String[] tokens = line.split(" ");
                //Hawal al-husul 'ala muarraf al-muwazzaf ka raqam
                try {
                    int eid =  Integer.parseInt(tokens[0]);
                } catch ( NumberFormatException ex) {
                    System.out.println("Khata fi muarraf al-muwazzaf.");
                }
                String name = tokens[1];
                double total = 0.0;
                for (int i = 2; i < tokens.length; i++ ) {
                    try {
                        total += Double.parseDouble(tokens[i]);
                    } catch (  NumberFormatException ex ) {
                        System.out.println("Khata fi al-saa'a.");
                    }
                }
                System.out.println("Majmu' al-saat al-amal li " + name + " = " + total);
            }     
            //Khatwa 1.1.3: Ighlaq object BufferedReader al-murabit bial-malaf
            br.close();
        }
        //Khatwa 1.2: Ta'amul ma'a jami' al-istithna'at al-mumkina allati qad turmee fi qita' try
        catch (FileNotFoundException ex) {
            System.out.println("Al-malaf lam yujad");
        }  catch (IOException ex ) {
            System.out.println("Mushkila ma'a al-malaf!");
        }
    }
}
